R=[
 record('fallout-watoga-prewar-exclusion','c0583','Fallout 76 — Watoga before the sabotage','Fallout 76','The functioning automated city’s resident and displaced human population',['game'],
 scope('Fallout 76 game history','The established pre-War city before Operation Free Watoga','Living residents and people displaced or excluded by Watoga’s automation',['Post-War empty robot patrols as leisure citizens','All Appalachia as receiving city benefits','Fanfiction descriptions']),
 'Watoga implements a largely automated municipal service system, while machine replacement drives unemployment and people out of the city. Access follows property wealth and corporate approval rather than a universal claim on the robot output. It is retained as an unequal automation-transition case: productive displacement is real, but displaced people do not thereby receive secure necessities. The high guarantee-axis value reflects costly residency, rejected applications and deliberately restricted services, rather than claiming every rich resident is deprived.\n\nCorporate authorities and privileged residents shape admission and service policy. That supports concentrated human control despite extensive robot operation; an automated city is not automatically an AI sovereign. The scope precedes the sabotage and nuclear catastrophe, whose hostile patrols are a different condition. No nonworking fraction is inferred from unemployment: people may seek other jobs, care for others or undertake useful activity. The description also does not convert robot municipal services into proof that every commodity is produced locally or free of charge.',
 {'guarantees':0.85,'control':0.05,'nonworking':None},
 {'guarantees':assessment(0.85,[0.6,1],'medium','Automation displaces people while wealth and corporate approval restrict residence and services.',w),
  'control':assessment(0.05,[0,0.2],'medium','Corporate admission decisions and elite service votes determine access; robot operation does not erase human policy control.',w),
  'nonworking':assessment(None,None,'low','Unemployment and outmigration are not an all-person census of useful work.',w)},
 3,w,[evidence('Actual automated services and unemployment coexist with corporate residency exclusion.',w,'Pre-War background and Operation Free Watoga','secondary_game_history_with_terminal_citations')],
 ['An unequal partial transition, not general freedom from subsistence work.', 'Pre-sabotage history only.', 'Municipal automation does not establish local automatic production of every good.', 'Participation remains unresolved.']),
 record('fallout-vault112-active-captives','c0584','Fallout 3 — Vault 112’s active simulation captives','Fallout 3','Living long-term residents maintained in Tranquility loungers',['game'],
 scope('Fallout 3','The continuing Braun-controlled simulation before player intervention','Living longtime human residents with active simulated experiences',['Empty pods and simulated bystanders as additional humans','James and the player as representative permanent residents','Unconscious cryostasis residents of other vaults','Post-failsafe dead residents']),
 'Vault 112 keeps living residents inside continuing virtual experiences while machinery and caretaker Robobrains sustain the physical facility. They do not obtain bodily support through current outside employment. This is an actual long-running captive support unit, not merely stored data or an empty simulation. Its guarantee estimate is deliberately broad: bodily maintenance persists for generations, but residents cannot leave or hold their provider accountable. Virtual killings and memory resets are not automatically physical deaths, although the intervention that ends the experiment can make the threat real.\n\nControl belongs to the human overseer Stanislaus Braun, rather than the maintenance robots or the residents collectively. Material support and severe coercion are recorded separately, with the possibility of withdrawal qualifying security. Active mental life does not imply that every resident performs no useful activity; simulated care and other meaningful work still count. No reliable participation census was found, so that axis remains unresolved. This record covers the established captive community before intervention, excluding temporary visitors, purely simulated neighbors and the dead population after a lethal failsafe.',
 {'guarantees':-0.3,'control':0,'nonworking':None},
 {'guarantees':assessment(-0.3,[-0.85,0.75],'low','Long-lasting physical support is real, but captives have no enforceable claim and lethal termination remains possible.',v),
  'control':assessment(0,[0,0.05],'medium','Braun is a living human overseer controlling the simulation; caretaker robots do not establish an AI ruler.',v),
  'nonworking':assessment(None,None,'low','Pod maintenance replaces external subsistence work, but active mental activity and useful simulated work are not censused.',v)},
 1,v,[evidence('Robots maintain the vault while living humans remain in Braun-controlled active simulations.',v,'Vault background, caretaker maintenance and Tranquility Lounger description','secondary_game_reference')],
 ['Coercion is distinct from automatic withdrawal of bodily provision.', 'Physical residents, active experiences and simulated bystanders are distinguished.', 'No participation census or fixed resident count is invented.', 'The lethal ending is outside the provision period.'],alternatives=[3]),
 record('invisible-war-helios-union','c0592','Deus Ex: Invisible War — ApostleCorp’s Helios Union','Deus Ex: Invisible War','Humanity in the realized ApostleCorp ending at Union year 125',['game'],
 scope('Deus Ex: Invisible War','The narrated mature Union, 125 years after the ApostleCorp branch','Living humanity linked through the universal nanite/Helios system',['Other mutually exclusive endings','The original Deus Ex merger as already achieving this order','Unmade sequel concepts'],branch='ApostleCorp Great Advance ending',player_configurable=True),
 'The ApostleCorp ending goes beyond an immediate promise: its later narration reports completed economic automation and an enduring Union in which people’s needs are treated collectively. That supports a post-work material system, with a moderately strong guarantee estimate. The score remains uncertain because the short ending gives no detailed inventory of housing, care or possible exclusion. This is one realized player-selected branch, not the outcome of every playthrough or a claim that the original game’s merger already achieved the same economy.\n\nHelios coordinates linked human minds and voices their consensus. The actual balance between shared human agency and the AI’s decisive authority is ambiguous, so control remains unresolved, with both AI provision and distributed-human provision interpretations recorded. Calling the link a democracy does not settle that balance. The ending explicitly preserves research, and freedom from necessary production work does not mean an absence of useful chosen activity. No nonworking percentage is supplied. Unused sequel plans and the other endings do not extend this branch’s constitution.',
 {'guarantees':-0.6,'control':None,'nonworking':None},
 {'guarantees':assessment(-0.6,[-0.9,0.25],'low','Completed economic automation and collective needs support a material floor, but the ending lacks detailed entitlements.',h),
  'control':assessment(None,None,'low','Human consensus, a merged human leader and Helios coordination coexist; decisive productive agency is not resolved.',h),
  'nonworking':assessment(None,None,'low','Economic automation coexists with continuing research; no all-person participation rate is given.',h)},
 5,h,[evidence('The mature selected ending explicitly reports completed economic automation and collective needs.',h,'ApostleCorp ending narration at Union year 125; route and project context','transcribed_primary_ending_and_secondary_context')],
 ['Mutually exclusive realized branch, not universal canon.', 'AI versus linked-human effective control remains unresolved.', 'Research remains useful work; automation is not a participation census.', 'The material-floor estimate is an interpretation of brief ending narration.'],alternatives=[2])
]
